def _run_physics(*, seed: int | None) -> object:
    runner = DubinsRaceRunner()
    kwargs: dict[str, object] = {
        "record_poses": True,
        "physics_mode": True,
    }
    if seed is not None:
        kwargs["planner_rng_seed"] = seed
    return runner.run(**kwargs)
